-- SB-79: a favour needs approval. When Mia does Leo's chore (SB-74), it's
-- recorded as "Mia says she did it" and nobody gets points yet. Leo approves
-- it (it's his chore), or Mia asks a parent, whose decision is final. See
-- "Favours need approval" in ../README.md.
--
-- The first ten statements are generated by drizzle-kit: the approval enum
-- and columns on chore_completions, the "one open completion per instance"
-- index rebuilt so a declined favour no longer counts as open, an index for
-- pending favours, and a check that only approved rows are reopened.
-- Existing rows default to `approved`, which is what they are. The rest is
-- hand-written, because drizzle-kit doesn't manage functions:
--
-- - app.complete_chore_instance / app.complete_chore_stage take an optional
--   `acting_as` (the member whose profile is open on a shared device) and
--   return the completion's `approval_status`. A favour (the doer isn't the
--   assignee) by someone who isn't acting as a parent is written `pending`:
--   no ledger row and no rotation hand-off, but the stage progress is kept.
--   Their argument lists change, so each is dropped and created again (one
--   function each, so no ambiguous overloads) and EXECUTE is granted again.
--   The new argument defaults to NULL, so existing calls keep working.
-- - New app.decide_favour(completion, approve, acting_as) and
--   app.escalate_favour(completion, acting_as).
-- - app.reopen_chore_completion only reopens approved completions.
-- - New internal app.favour_actor(household, acting_as): who the caller is
--   acting as, and whether that counts as a parent.
--
-- Custom SQLSTATEs raised here (mapped to errors in ../src/completions.ts),
-- on top of CP001-CP004:
--   CP005  the completion isn't a favour awaiting a decision (it never needed
--          approval, or it was reopened), or reopening one that isn't approved
--   CP006  the doer asked a parent, so only a parent can decide it now
--   CP007  the chore has been completed again since the favour was declined
--   CP008  a parent already declined it, and a parent's decision is final

CREATE TYPE "public"."completion_approval_status" AS ENUM('approved', 'pending', 'declined');--> statement-breakpoint
DROP INDEX "chore_completions_instance_id_open_key";--> statement-breakpoint
ALTER TABLE "chore_completions" ADD COLUMN "approval_status" "completion_approval_status" DEFAULT 'approved' NOT NULL;--> statement-breakpoint
ALTER TABLE "chore_completions" ADD COLUMN "decided_by_member_id" uuid;--> statement-breakpoint
ALTER TABLE "chore_completions" ADD COLUMN "decided_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "chore_completions" ADD COLUMN "escalated_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "chore_completions" ADD CONSTRAINT "chore_completions_decided_by_member_id_household_members_id_fk" FOREIGN KEY ("decided_by_member_id") REFERENCES "public"."household_members"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "chore_completions_household_id_pending_idx" ON "chore_completions" USING btree ("household_id") WHERE "chore_completions"."approval_status" = 'pending';--> statement-breakpoint
CREATE UNIQUE INDEX "chore_completions_instance_id_open_key" ON "chore_completions" USING btree ("instance_id") WHERE "chore_completions"."reopened_at" is null and "chore_completions"."approval_status" <> 'declined';--> statement-breakpoint
ALTER TABLE "chore_completions" ADD CONSTRAINT "chore_completions_reopen_approved_check" CHECK ("chore_completions"."reopened_at" is null or "chore_completions"."approval_status" = 'approved');
--> statement-breakpoint

-- Who the signed-in user is acting as in `household`, and whether that counts
-- as a parent. Internal: used by the completion and favour functions.
--
-- `acting_as` is the member whose profile is open on a shared device (the
-- web app passes it while a parent's session is on a managed kid's profile).
-- NULL, or the user's own member, means they're acting as themselves, and a
-- parent then counts as a parent. Any other member must be someone they can
-- act as (a managed kid they parent), and then they're that kid, not a
-- parent: a kid on the family tablet can't approve their own favour, or have
-- a favour approved straight away, just because a parent is signed in.
CREATE FUNCTION app.favour_actor(household uuid, acting_as uuid)
	RETURNS TABLE (actor uuid, as_parent boolean)
	LANGUAGE plpgsql STABLE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		own uuid;
	BEGIN
		own := app.current_member_id(household);
		IF acting_as IS NULL OR acting_as = own THEN
			RETURN QUERY SELECT own, app.is_household_parent(household);
			RETURN;
		END IF;
		IF NOT (app.is_member_id_in(household, acting_as) AND app.can_act_as_member(acting_as)) THEN
			RAISE EXCEPTION 'you can''t act as member % here', acting_as
				USING ERRCODE = 'insufficient_privilege';
		END IF;
		RETURN QUERY SELECT acting_as, false;
	END
	$$;
--> statement-breakpoint

DROP FUNCTION app.complete_chore_stage(uuid, uuid, uuid);
--> statement-breakpoint
DROP FUNCTION app.complete_chore_instance(uuid, uuid);
--> statement-breakpoint

-- Completes a chore for one period. Idempotent: if the instance already has
-- an open completion (approved, or a pending favour), it returns that one
-- with `points = 0` and `already_completed = true`, and writes nothing. So a
-- pending favour blocks the assignee completing the chore themselves: they
-- approve or decline it instead.
--
-- `done_by` works as in 0022 (app.authorize_chore_doer decides who may name
-- whom). `acting_as` is the profile open on a shared device (see
-- app.favour_actor); while it's set, only that member or the assignee can be
-- named as the doer.
--
-- When the doer is the assignee, or the caller is acting as a parent, the
-- completion is `approved` as before: the points go to the doer and a
-- rotation turn advances. Otherwise it's a favour waiting for a decision
-- (`pending`, see app.decide_favour): `points` is 0, there's no ledger row
-- and the turn stays where it is. `credited_member_id` is still the doer, who
-- gets the completion's points if it's approved.
CREATE FUNCTION app.complete_chore_instance(
	instance uuid,
	done_by uuid DEFAULT NULL,
	acting_as uuid DEFAULT NULL
)
	RETURNS TABLE (
		completion_id uuid,
		points integer,
		already_completed boolean,
		next_member_id uuid,
		credited_member_id uuid,
		approval_status text
	)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		i public.chore_instances%ROWTYPE;
		c public.chores%ROWTYPE;
		doer uuid;
		who record;
		status public.completion_approval_status;
		existing public.chore_completions%ROWTYPE;
		new_completion uuid;
		stage_count integer;
		done_count integer;
		next_turn uuid;
	BEGIN
		SELECT * INTO i FROM public.chore_instances ci WHERE ci.id = instance FOR UPDATE;
		IF NOT FOUND OR NOT app.is_household_member(i.household_id) THEN
			RAISE EXCEPTION 'no chore instance %', instance USING ERRCODE = 'no_data_found';
		END IF;
		IF i.assigned_member_id IS NULL THEN
			RAISE EXCEPTION 'chore instance % has no assignee', instance USING ERRCODE = 'CP003';
		END IF;
		doer := app.authorize_chore_doer(i.household_id, i.assigned_member_id, done_by);
		SELECT * INTO who FROM app.favour_actor(i.household_id, acting_as);
		IF acting_as IS NOT NULL AND doer <> i.assigned_member_id AND doer IS DISTINCT FROM who.actor THEN
			RAISE EXCEPTION 'on a profile, only that member can be recorded as who did this chore'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		SELECT * INTO existing
		FROM public.chore_completions cc
		WHERE cc.instance_id = instance
			AND cc.reopened_at IS NULL
			AND cc.approval_status <> 'declined';
		IF FOUND THEN
			RETURN QUERY SELECT existing.id, 0, true, NULL::uuid,
				coalesce(existing.done_by_member_id, existing.member_id),
				existing.approval_status::text;
			RETURN;
		END IF;

		SELECT * INTO c FROM public.chores ch WHERE ch.id = i.chore_id;

		SELECT count(*) INTO stage_count FROM public.chore_stages s WHERE s.chore_id = i.chore_id;
		SELECT count(*) INTO done_count FROM public.chore_stage_progress sp WHERE sp.instance_id = instance;
		IF done_count < stage_count THEN
			RAISE EXCEPTION 'chore % has % of % stages left', i.chore_id, stage_count - done_count, stage_count
				USING ERRCODE = 'CP002';
		END IF;

		status := CASE
			WHEN doer <> i.assigned_member_id AND NOT who.as_parent THEN 'pending'
			ELSE 'approved'
		END;

		INSERT INTO public.chore_completions (
			household_id, chore_id, instance_id, member_id, done_by_member_id, points, approval_status
		)
		VALUES (
			i.household_id, i.chore_id, instance, i.assigned_member_id,
			CASE WHEN doer <> i.assigned_member_id THEN doer END,
			c.points, status
		)
		RETURNING id INTO new_completion;

		IF status = 'pending' THEN
			RETURN QUERY SELECT new_completion, 0, false, NULL::uuid, doer, status::text;
			RETURN;
		END IF;

		IF c.points > 0 THEN
			INSERT INTO public.points_ledger (household_id, member_id, delta, reason, completion_id)
			VALUES (i.household_id, doer, c.points, 'completion', new_completion);
		END IF;

		IF c.type::text = 'rotation' THEN
			-- Authorized above (a parent, the turn-holder, or the doer), so this
			-- skips advance_chore_rotation's own "whose turn is it" check, which a
			-- doer who can't act as the turn-holder would fail.
			SELECT a.member_id INTO next_turn
			FROM app.advance_chore_rotation_turn(i.chore_id, i.assigned_member_id, true) a;
		END IF;

		RETURN QUERY SELECT new_completion, c.points, false, next_turn, doer, status::text;
	END
	$$;
--> statement-breakpoint

-- As in 0022, plus `acting_as` (passed through to complete_chore_instance)
-- and the completion's `approval_status` when the last stage completed the
-- chore. Stage progress is recorded for the doer even when the completion is
-- a pending favour, so the steps show as done by them.
CREATE FUNCTION app.complete_chore_stage(
	instance uuid,
	stage uuid,
	done_by uuid DEFAULT NULL,
	acting_as uuid DEFAULT NULL
)
	RETURNS TABLE (
		chore_completed boolean,
		completion_id uuid,
		points integer,
		already_completed boolean,
		next_member_id uuid,
		credited_member_id uuid,
		approval_status text
	)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		i public.chore_instances%ROWTYPE;
		s public.chore_stages%ROWTYPE;
		doer uuid;
		who record;
		stage_count integer;
		done_count integer;
		r record;
	BEGIN
		SELECT * INTO i FROM public.chore_instances ci WHERE ci.id = instance FOR UPDATE;
		IF NOT FOUND OR NOT app.is_household_member(i.household_id) THEN
			RAISE EXCEPTION 'no chore instance %', instance USING ERRCODE = 'no_data_found';
		END IF;
		IF i.assigned_member_id IS NULL THEN
			RAISE EXCEPTION 'chore instance % has no assignee', instance USING ERRCODE = 'CP003';
		END IF;
		doer := app.authorize_chore_doer(i.household_id, i.assigned_member_id, done_by);
		SELECT * INTO who FROM app.favour_actor(i.household_id, acting_as);
		IF acting_as IS NOT NULL AND doer <> i.assigned_member_id AND doer IS DISTINCT FROM who.actor THEN
			RAISE EXCEPTION 'on a profile, only that member can be recorded as who did this chore'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		SELECT * INTO s FROM public.chore_stages st WHERE st.id = stage AND st.chore_id = i.chore_id;
		IF NOT FOUND THEN
			RAISE EXCEPTION 'stage % is not a stage of chore %', stage, i.chore_id
				USING ERRCODE = 'no_data_found';
		END IF;

		IF EXISTS (
			SELECT 1 FROM public.chore_stages p
			WHERE p.chore_id = i.chore_id
				AND p.position < s.position
				AND NOT EXISTS (
					SELECT 1 FROM public.chore_stage_progress sp
					WHERE sp.instance_id = instance AND sp.stage_id = p.id
				)
		) THEN
			RAISE EXCEPTION 'an earlier stage of chore % is not done yet', i.chore_id
				USING ERRCODE = 'CP001';
		END IF;

		INSERT INTO public.chore_stage_progress (instance_id, stage_id, chore_id, household_id, completed_by_member_id)
		VALUES (instance, stage, i.chore_id, i.household_id, doer)
		ON CONFLICT (instance_id, stage_id) DO NOTHING;

		SELECT count(*) INTO stage_count FROM public.chore_stages st WHERE st.chore_id = i.chore_id;
		SELECT count(*) INTO done_count FROM public.chore_stage_progress sp WHERE sp.instance_id = instance;
		IF done_count < stage_count THEN
			RETURN QUERY SELECT false, NULL::uuid, 0, false, NULL::uuid, NULL::uuid, NULL::text;
			RETURN;
		END IF;

		SELECT * INTO r FROM app.complete_chore_instance(instance, done_by, acting_as);
		RETURN QUERY SELECT true, r.completion_id, r.points, r.already_completed, r.next_member_id,
			r.credited_member_id, r.approval_status;
	END
	$$;
--> statement-breakpoint

-- Approves (`approve` true) or declines a favour. `acting_as` is the profile
-- open on a shared device, as for the completion functions.
--
-- Who may decide:
-- - Never the doer, whoever they are (42501).
-- - The assignee (their own login, or a parent on their managed-kid profile),
--   while the favour is pending and the doer hasn't asked a parent (CP006
--   once they have). Once anyone has decided, the assignee's call changes
--   nothing, so the assignee can't overturn a parent.
-- - Any parent acting as themselves, on a pending favour or on one the
--   assignee declined: a parent's decision overrides a decline (CP007 if the
--   chore has been completed again since). A parent declining one the
--   assignee already declined makes the decline final (the doer can't ask a
--   parent any more). Once a parent has decided, deciding again changes
--   nothing.
-- - Nobody else (42501), and nobody outside the household (P0002).
-- - CP005 when the completion never needed approval, or was reopened.
--
-- Approving writes the doer's `completion` ledger row (the points copied when
-- it was done) and, for a rotation chore still on the assignee's turn,
-- advances the turn as a completion would. Stages a decline cleared are
-- checked again for the doer. Declining marks it `declined` and unchecks the
-- stages the doer checked, so the chore is open again for the assignee
-- (stages the assignee checked themselves stay checked).
--
-- Locks the instance, then the completion (the same order as completing), so
-- an assignee and a parent deciding at once take turns and the second sees
-- the first's decision. Returns the status afterwards, whether this call
-- changed anything, the points it awarded, the turn's next member, and who
-- the decision is now recorded for.
CREATE FUNCTION app.decide_favour(
	completion uuid,
	approve boolean,
	acting_as uuid DEFAULT NULL
)
	RETURNS TABLE (
		approval_status text,
		changed boolean,
		points integer,
		next_member_id uuid,
		decided_by_member_id uuid
	)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		target public.chore_completions%ROWTYPE;
		cc public.chore_completions%ROWTYPE;
		who record;
		kind text;
		rot public.chore_rotations%ROWTYPE;
		assignee_declined boolean;
		awarded integer := 0;
		next_turn uuid;
	BEGIN
		SELECT * INTO target FROM public.chore_completions x WHERE x.id = completion;
		IF NOT FOUND OR NOT app.is_household_member(target.household_id) THEN
			RAISE EXCEPTION 'no completion %', completion USING ERRCODE = 'no_data_found';
		END IF;
		PERFORM 1 FROM public.chore_instances ci WHERE ci.id = target.instance_id FOR UPDATE;
		SELECT * INTO cc FROM public.chore_completions x WHERE x.id = completion FOR UPDATE;

		IF cc.reopened_at IS NOT NULL OR (cc.approval_status = 'approved' AND cc.decided_at IS NULL) THEN
			RAISE EXCEPTION 'completion % is not a favour waiting for a decision', completion
				USING ERRCODE = 'CP005';
		END IF;

		SELECT * INTO who FROM app.favour_actor(cc.household_id, acting_as);
		IF who.actor IS NOT DISTINCT FROM cc.done_by_member_id THEN
			RAISE EXCEPTION 'you can''t decide a favour you did yourself'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		assignee_declined := cc.approval_status = 'declined'
			AND cc.escalated_at IS NULL
			AND cc.decided_by_member_id = cc.member_id;

		IF who.as_parent THEN
			IF NOT (cc.approval_status = 'pending' OR assignee_declined) THEN
				-- A parent already decided it: final.
				RETURN QUERY SELECT cc.approval_status::text, false, 0, NULL::uuid, cc.decided_by_member_id;
				RETURN;
			END IF;
			IF assignee_declined AND NOT approve THEN
				-- The assignee's decline stands, and now it's a parent's: final.
				UPDATE public.chore_completions x
				SET decided_by_member_id = who.actor, decided_at = now()
				WHERE x.id = completion;
				RETURN QUERY SELECT 'declined'::text, true, 0, NULL::uuid, who.actor;
				RETURN;
			END IF;
		ELSIF who.actor IS NOT DISTINCT FROM cc.member_id THEN
			IF cc.approval_status <> 'pending' THEN
				RETURN QUERY SELECT cc.approval_status::text, false, 0, NULL::uuid, cc.decided_by_member_id;
				RETURN;
			END IF;
			IF cc.escalated_at IS NOT NULL THEN
				RAISE EXCEPTION 'a parent has been asked to decide this favour'
					USING ERRCODE = 'CP006';
			END IF;
		ELSE
			RAISE EXCEPTION 'only the member whose chore it is, or a parent, can decide this favour'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		IF NOT approve THEN
			UPDATE public.chore_completions x
			SET approval_status = 'declined', decided_by_member_id = who.actor, decided_at = now()
			WHERE x.id = completion;
			DELETE FROM public.chore_stage_progress sp
			WHERE sp.instance_id = cc.instance_id
				AND sp.completed_by_member_id IS NOT DISTINCT FROM cc.done_by_member_id;
			RETURN QUERY SELECT 'declined'::text, true, 0, NULL::uuid, who.actor;
			RETURN;
		END IF;

		-- Approving a declined favour takes the instance back for it, so nothing
		-- else may have completed it since.
		IF cc.approval_status = 'declined' AND EXISTS (
			SELECT 1 FROM public.chore_completions o
			WHERE o.instance_id = cc.instance_id
				AND o.id <> cc.id
				AND o.reopened_at IS NULL
				AND o.approval_status <> 'declined'
		) THEN
			RAISE EXCEPTION 'the chore has been completed again since this favour was declined'
				USING ERRCODE = 'CP007';
		END IF;

		UPDATE public.chore_completions x
		SET approval_status = 'approved', decided_by_member_id = who.actor, decided_at = now()
		WHERE x.id = completion;

		INSERT INTO public.chore_stage_progress (instance_id, stage_id, chore_id, household_id, completed_by_member_id)
		SELECT cc.instance_id, st.id, st.chore_id, cc.household_id, cc.done_by_member_id
		FROM public.chore_stages st
		WHERE st.chore_id = cc.chore_id
		ON CONFLICT (instance_id, stage_id) DO NOTHING;

		-- The doer may have left the household since; then nobody gets the points.
		IF cc.points > 0 AND cc.done_by_member_id IS NOT NULL THEN
			INSERT INTO public.points_ledger (household_id, member_id, delta, reason, completion_id)
			VALUES (cc.household_id, cc.done_by_member_id, cc.points, 'completion', completion);
			awarded := cc.points;
		END IF;

		SELECT ch.type::text INTO kind FROM public.chores ch WHERE ch.id = cc.chore_id;
		IF kind = 'rotation' THEN
			-- Only while it's still the assignee's turn: if a parent skipped them
			-- meanwhile, or they've since done a later turn, the turn has already
			-- moved on and stays where it is.
			SELECT * INTO rot FROM public.chore_rotations r WHERE r.chore_id = cc.chore_id FOR UPDATE;
			IF FOUND AND rot.current_member_id IS NOT DISTINCT FROM cc.member_id THEN
				SELECT a.member_id INTO next_turn
				FROM app.advance_chore_rotation_turn(cc.chore_id, cc.member_id, true) a;
			END IF;
		END IF;

		RETURN QUERY SELECT 'approved'::text, true, awarded, next_turn, who.actor;
	END
	$$;
--> statement-breakpoint

-- The doer asks a parent to decide their favour ("Ask a parent"), when the
-- assignee hasn't answered or declined it. Only the doer can (their own
-- login, or a parent on their managed-kid profile via `acting_as`); anyone
-- else gets 42501. From then on only a parent can decide it.
--
-- - Pending: sets `escalated_at`.
-- - Declined by the assignee: back to `pending`, with `escalated_at` set
--   (`decided_by_member_id` / `decided_at` still say who declined it, until a
--   parent decides). CP007 if the chore has been completed again since.
-- - Declined by a parent: CP008, a parent's decision is final.
-- - Already escalated, or approved: changes nothing.
-- - Not a favour, or reopened: CP005.
--
-- Same locks as app.decide_favour. Returns the status afterwards, whether
-- this call changed anything, and `escalated_at`.
CREATE FUNCTION app.escalate_favour(completion uuid, acting_as uuid DEFAULT NULL)
	RETURNS TABLE (approval_status text, changed boolean, escalated_at timestamptz)
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		target public.chore_completions%ROWTYPE;
		cc public.chore_completions%ROWTYPE;
		who record;
		asked_at timestamptz := now();
	BEGIN
		SELECT * INTO target FROM public.chore_completions x WHERE x.id = completion;
		IF NOT FOUND OR NOT app.is_household_member(target.household_id) THEN
			RAISE EXCEPTION 'no completion %', completion USING ERRCODE = 'no_data_found';
		END IF;
		PERFORM 1 FROM public.chore_instances ci WHERE ci.id = target.instance_id FOR UPDATE;
		SELECT * INTO cc FROM public.chore_completions x WHERE x.id = completion FOR UPDATE;

		IF cc.reopened_at IS NOT NULL OR (cc.approval_status = 'approved' AND cc.decided_at IS NULL) THEN
			RAISE EXCEPTION 'completion % is not a favour waiting for a decision', completion
				USING ERRCODE = 'CP005';
		END IF;

		SELECT * INTO who FROM app.favour_actor(cc.household_id, acting_as);
		IF cc.done_by_member_id IS NULL OR who.actor IS DISTINCT FROM cc.done_by_member_id THEN
			RAISE EXCEPTION 'only the member who did this favour can ask a parent'
				USING ERRCODE = 'insufficient_privilege';
		END IF;

		IF cc.escalated_at IS NOT NULL OR cc.approval_status = 'approved' THEN
			RETURN QUERY SELECT cc.approval_status::text, false, cc.escalated_at;
			RETURN;
		END IF;

		IF cc.approval_status = 'declined' THEN
			IF cc.decided_by_member_id IS DISTINCT FROM cc.member_id THEN
				RAISE EXCEPTION 'a parent already decided this favour'
					USING ERRCODE = 'CP008';
			END IF;
			IF EXISTS (
				SELECT 1 FROM public.chore_completions o
				WHERE o.instance_id = cc.instance_id
					AND o.id <> cc.id
					AND o.reopened_at IS NULL
					AND o.approval_status <> 'declined'
			) THEN
				RAISE EXCEPTION 'the chore has been completed again since this favour was declined'
					USING ERRCODE = 'CP007';
			END IF;
		END IF;

		UPDATE public.chore_completions x
		SET approval_status = 'pending', escalated_at = asked_at
		WHERE x.id = completion;
		RETURN QUERY SELECT 'pending'::text, true, asked_at;
	END
	$$;
--> statement-breakpoint

-- As in 0022, except only an approved completion can be reopened (CP005): a
-- pending favour has no points to take back, so a parent declines it instead.
CREATE OR REPLACE FUNCTION app.reopen_chore_completion(completion uuid)
	RETURNS boolean
	LANGUAGE plpgsql VOLATILE SECURITY DEFINER
	SET search_path = pg_catalog, public
	AS $$
	DECLARE
		cc public.chore_completions%ROWTYPE;
		awarded public.points_ledger%ROWTYPE;
	BEGIN
		SELECT * INTO cc FROM public.chore_completions x WHERE x.id = completion FOR UPDATE;
		IF NOT FOUND OR NOT app.is_household_member(cc.household_id) THEN
			RAISE EXCEPTION 'no completion %', completion USING ERRCODE = 'no_data_found';
		END IF;
		IF NOT app.is_household_parent(cc.household_id) THEN
			RAISE EXCEPTION 'only a parent can reopen a completion'
				USING ERRCODE = 'insufficient_privilege';
		END IF;
		IF cc.reopened_at IS NOT NULL THEN
			RETURN false;
		END IF;
		IF cc.approval_status <> 'approved' THEN
			RAISE EXCEPTION 'completion % is a favour that hasn''t been approved; decline it instead', completion
				USING ERRCODE = 'CP005';
		END IF;

		UPDATE public.chore_completions x
		SET reopened_at = now(), reopened_by = app.current_user_id()
		WHERE x.id = completion;

		SELECT * INTO awarded
		FROM public.points_ledger pl
		WHERE pl.completion_id = completion AND pl.reason = 'completion';
		IF FOUND THEN
			INSERT INTO public.points_ledger (household_id, member_id, delta, reason, completion_id)
			VALUES (awarded.household_id, awarded.member_id, -awarded.delta, 'reversal', completion);
		END IF;

		DELETE FROM public.chore_stage_progress sp
		USING public.chore_stages st
		WHERE sp.instance_id = cc.instance_id
			AND sp.stage_id = st.id
			AND st.position = (
				SELECT max(s2.position) FROM public.chore_stages s2 WHERE s2.chore_id = cc.chore_id
			);

		RETURN true;
	END
	$$;
--> statement-breakpoint

REVOKE ALL ON FUNCTION
	app.favour_actor(uuid, uuid),
	app.complete_chore_instance(uuid, uuid, uuid),
	app.complete_chore_stage(uuid, uuid, uuid, uuid),
	app.decide_favour(uuid, boolean, uuid),
	app.escalate_favour(uuid, uuid)
	FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION
	app.complete_chore_instance(uuid, uuid, uuid),
	app.complete_chore_stage(uuid, uuid, uuid, uuid),
	app.decide_favour(uuid, boolean, uuid),
	app.escalate_favour(uuid, uuid)
	TO authenticated_backend;
